&lt;li&gt;&lt;a class=&quot;user-mention notranslate&quot; data-hovercard-type=&quot;user&quot; data-hovercard-url=&quot;/users/pjdurden/hovercard&quot; data-octo-click=&quot;hovercard-link-click&quot; data-octo-dimensions=&quot;link_type:self&quot; href=&quot;https://github.com/pjdurden&quot;&gt;@pjdurden&lt;/a&gt; made their first contribution in &lt;a class=&quot;issue-link js-issue-link&quot; data-error-text=&quot;Failed to load title&quot; data-id=&quot;4602510091&quot; data-permission-text=&quot;Title is private&quot; data-url=&quot;https://github.com/sgl-project/sglang/issues/27430&quot; data-hovercard-type=&quot;pull_request&quot; data-hovercard-url=&quot;/sgl-project/sglang/pull/27430/hovercard&quot; href=&quot;https://github.com/sgl-project/sglang/pull/27430&quot;&gt;#27430&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;user-mention notranslate&quot; data-hovercard-type=&quot;user&quot; data-hovercard-url=&quot;/users/EazyReal/hovercard&quot; data-octo-click=&quot;hovercard-link-click&quot; data-octo-dimensions=&quot;link_type:self&quot; href=&quot;https://github.com/EazyReal&quot;&gt;@EazyReal&lt;/a&gt; made their first contribution in &lt;a class=&quot;issue-link js-issue-link&quot; data-error-text=&quot;Failed to load title&quot; data-id=&quot;4708198413&quot; data-permission-text=&quot;Title is private&quot; data-url=&quot;https://github.com/sgl-project/sglang/issues/28802&quot; data-hovercard-type=&quot;pull_request&quot; data-hovercard-url=&quot;/sgl-project/sglang/pull/28802/hovercard&quot; href=&quot;https://github.com/sgl-project/sglang/pull/28802&quot;&gt;#28802&lt;/a&gt;&lt;/li&gt;
&lt;li&gt;&lt;a class=&quot;user-mention notranslate&quot; data-hovercard-type=&quot;user&quot; data-hovercard-url=&quot;/users/Terry-Uv/hovercard&quot; data-octo-click=&quot;hovercard-link-click&quot; data-octo-dimensions=&quot;link_type:self&quot; href=&quot;https://github.com/Terry-Uv&quot;&gt;@Terry-Uv&lt;/a&gt; made their first contribution in &lt;a class=&quot;issue-link js-issue-link&quot; data-error-text=&quot;Failed to load title&quot; data-id=&quot;4560166620&quot; data-permission-text=&quot;Title is private&quot; data-url=&quot;https://github.com/sgl-project/sglang/issues/26880&quot; data-hovercard-type=&quot;pull_request&quot; data-hovercard-url=&quot;/sgl-project/sglang/pull/26880/hovercard&quot; href=&quot;https://github.com/sgl-project/sglang/pull/26880&quot;&gt;#26880&lt;/a&gt;&lt;/li&gt;
